1	import { stateAfter } from '/src/queue.ts';
2	import { statusVisuals, statusCell, compactStatus, display } from '/src/queue-view-integration.ts';
3	
4	const panel = display.background;
5	document.documentElement.style.setProperty('--panel', panel);
6	const cache = new Map();
7	const cells = [];
8	const consumers = { statusCell, compactStatus };
9	const events = ['idle', 'started', 'pause', 'ok', 'error'].filter(event => event === 'idle' || statusVisuals[stateAfter(event)]);
10	document.querySelectorAll('[data-event]').forEach(button => { button.hidden = !events.includes(button.dataset.event); });
11	const errors = [];
12	window.addEventListener('error', event => errors.push(event.message));
13	window.addEventListener('unhandledrejection', event => errors.push(String(event.reason)));
14	const digest = async bytes => [...new Uint8Array(await crypto.subtle.digest('SHA-256', bytes))].map(x => x.toString(16).padStart(2, '0')).join('');
15	
16	async function imageFor(path) {
17	  if (!cache.has(path)) cache.set(path, (async () => {
18	    const response = await fetch(`/${path}`);
19	    if (!response.ok) return { available: false, status: response.status, path };
20	    const data = await response.arrayBuffer();
21	    const image = new Image();
22	    const url = URL.createObjectURL(new Blob([data], { type: response.headers.get('Content-Type') }));
23	    try { image.src = url; await image.decode(); }
24	    finally { URL.revokeObjectURL(url); }
25	    return { available: true, image, path, sha256: await digest(data), width: image.naturalWidth, height: image.naturalHeight };
26	  })());
27	  return cache.get(path);
28	}
29	
30	function paint(canvas, asset, frames, scale, elapsed) {
31	  const [width, height] = display.cell;
32	  const frame = Math.floor(Math.max(elapsed, 0) / display.frameMs) % frames;
33	  const context = canvas.getContext('2d', { willReadFrequently: true });
34	  context.imageSmoothingEnabled = display.filter !== 'nearest';
35	  context.fillStyle = panel;
36	  context.fillRect(0, 0, canvas.width, canvas.height);
37	  if (asset.available && asset.width === width * frames && asset.height === height) {
38	    context.drawImage(asset.image, frame * width, 0, width, height, 0, 0, width * scale, height * scale);
39	  }
40	  return frame;
41	}
42	
43	async function makeCell(consumer, state, scale, elapsed = 0, track = true) {
44	  const descriptor = consumers[consumer](state);
45	  const asset = await imageFor(descriptor.path);
46	  const node = document.createElement('div');
47	  node.className = `cell ${consumer === 'compactStatus' ? 'compact' : ''}`;
48	  const glyph = document.createElement('span'); glyph.className = 'glyph';
49	  const label = document.createElement('span'); label.textContent = descriptor.label;
50	  node.append(glyph, label);
51	  const info = { consumer, state, scale, descriptor, asset: { ...asset, image: undefined }, node, canvas: null, frame: 0 };
52	  if (asset.available) {
53	    const canvas = document.createElement('canvas');
54	    canvas.width = display.cell[0] * scale; canvas.height = display.cell[1] * scale;
55	    canvas.setAttribute('aria-label', `${descriptor.label} icon`);
56	    info.canvas = canvas; info.frame = paint(canvas, asset, descriptor.frames, scale, elapsed);
57	    info.geometryMatches = asset.width === display.cell[0] * descriptor.frames && asset.height === display.cell[1];
58	    glyph.append(canvas);
59	    if (!info.geometryMatches) { const warning = document.createElement('span'); warning.className = 'missing'; warning.textContent = 'Wrong sheet size'; node.append(warning); }
60	  } else {
61	    glyph.classList.add('missing'); glyph.textContent = 'Missing asset';
62	  }
63	  if (track) cells.push(info);
64	  return info;
65	}
66	
67	const matrix = document.querySelector('#matrix');
68	for (const text of ['State', 'Full · 1×', `Full · ${display.scale}×`, 'Compact · 1×', `Compact · ${display.scale}×`]) {
69	  const node = document.createElement('div'); node.className = 'heading'; node.textContent = text; matrix.append(node);
70	}
71	for (const state of Object.keys(statusVisuals)) {
72	  const label = document.createElement('div'); label.className = 'row-label'; label.textContent = state; matrix.append(label);
73	  for (const consumer of Object.keys(consumers)) for (const scale of [1, display.scale]) matrix.append((await makeCell(consumer, state, scale)).node);
74	}
75	const missing = [...cache.keys()].filter(path => !cells.find(cell => cell.descriptor.path === path)?.asset.available);
76	document.querySelector('#coverage').textContent = missing.length ? `${missing.length} status assets are still missing: ${missing.join(', ')}` : 'Every mapped status asset is available; visual review remains separate.';
77	
78	let livePromise;
79	let liveCells = [];
80	let playbackObserver = null;
81	let origin = performance.now();
82	async function select(event) {
83	  const state = event === 'idle' ? 'idle' : stateAfter(event);
84	  liveCells = await Promise.all(Object.keys(consumers).map(consumer => makeCell(consumer, state, display.scale, 0, false)));
85	  document.querySelector('#live').replaceChildren(...liveCells.map(cell => cell.node));
86	  document.querySelector('#live-title').textContent = `Current queue state · ${state}`;
87	  origin = performance.now();
88	  return { event, state, consumers: liveCells.map(({ consumer, descriptor, asset }) => ({ consumer, descriptor, available: asset.available, sha256: asset.sha256 })) };
89	}
90	document.querySelectorAll('[data-event]').forEach(button => button.addEventListener('click', () => { livePromise = select(button.dataset.event); }));
91	await select('ok');
92	function animate(now) {
93	  const current = liveCells;
94	  Promise.all(current.map(async cell => {
95	    if (cell.canvas && cell.descriptor.frames > 1) {
96	      const asset = await cache.get(cell.descriptor.path);
97	      cell.frame = paint(cell.canvas, asset, cell.descriptor.frames, cell.scale, now - origin);
98	    }
99	  })).then(() => { if (current === liveCells) playbackObserver?.(now, current); });
100	  requestAnimationFrame(animate);
101	}
102	requestAnimationFrame(animate);
103	
104	async function capturePlayback() {
105	  const transition = await select('started');
106	  const descriptor = statusCell(transition.state);
107	  if (!liveCells.every(cell => cell.canvas && cell.geometryMatches) || descriptor.frames <= 1) {
108	    return { status: 'unavailable', transition, reason: 'Mapped animation is absent or has incompatible geometry', samples: [] };
109	  }
110	  const duration = display.frameMs * descriptor.frames * 3 + display.frameMs / 2;
111	  return new Promise(resolve => {
112	    const samples = [];
113	    let previous = null;
114	    let finished = false;
115	    const finish = (status, reason) => {
116	      if (finished) return;
117	      finished = true; playbackObserver = null; clearTimeout(timer);
118	      resolve({ status, reason, transition, frameMs: display.frameMs, frameCount: descriptor.frames, durationMs: duration, visibility: document.visibilityState, samples });
119	    };
120	    const timer = setTimeout(() => finish('unavailable', 'Live animation callbacks did not cover the requested duration'), 5000);
121	    playbackObserver = (now, current) => {
122	      const elapsed = Math.max(0, now - origin);
123	      const key = current.map(cell => cell.frame).join(',');
124	      if (key !== previous) {
125	        samples.push({ elapsed, cells: current.map(cell => ({ consumer: cell.consumer, descriptor: cell.descriptor, frame: cell.frame, scale: cell.scale, sha256: cell.asset.sha256, png: cell.canvas.toDataURL() })) });
126	        previous = key;
127	      }
128	      if (elapsed >= duration) finish('observed', 'Actual requestAnimationFrame painting in both live consumers; artistic motion judgment is separate');
129	    };
130	  });
131	}
132	
133	async function capture() {
134	  await document.fonts.ready;
135	  const transitions = [];
136	  for (const event of events) {
137	    const button = document.querySelector(`[data-event="${event}"]`);
138	    button.click(); transitions.push(await livePromise);
139	  }
140	  const playback = await capturePlayback();
141	  document.querySelector('[data-event="ok"]').click(); await livePromise;
142	  const timeline = [];
143	  for (const state of Object.keys(statusVisuals)) {
144	    const descriptor = statusCell(state);
145	    if (descriptor.frames <= 1) continue;
146	    const boundaries = Array.from({ length: descriptor.frames }, (_, i) => [i * display.frameMs, (i + 1) * display.frameMs - 1]).flat();
147	    for (const elapsed of [...boundaries, display.frameMs * descriptor.frames]) {
148	      const cell = await makeCell('statusCell', state, 1, elapsed, false);
149	      timeline.push({ state, elapsed, available: cell.asset.available, frame: cell.canvas ? cell.frame : null, png: cell.canvas?.toDataURL() });
150	    }
151	  }
152	  const views = cells.map(({ node, canvas, ...info }) => ({ ...info, canvas: undefined,
153	    smoothing: canvas?.getContext('2d').imageSmoothingEnabled,
154	    bounds: canvas ? Object.fromEntries(['x', 'y', 'width', 'height'].map(key => [key, canvas.getBoundingClientRect()[key]])) : null,
155	    imageRendering: canvas ? getComputedStyle(canvas).imageRendering : null,
156	    png: canvas?.toDataURL(),
157	  }));
158	  return { version: 1, userAgent: navigator.userAgent, devicePixelRatio, viewport: { width: innerWidth, height: innerHeight, clientWidth: document.documentElement.clientWidth }, display, transitions, timeline, playback, views, missing, errors,
159	    scope: 'Actual browser execution of the supplied queue modules, decode, canvas crop/scale/compositing and DOM event handlers. Image provenance and visual/style acceptance are separate.' };
160	}
161	window.captureQueue = capture;
162	if (new URL(location.href).searchParams.has('capture')) {
163	  const report = await capture();
164	  await fetch('/__capture', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(report) });
165	  document.body.dataset.captureComplete = 'true';
166	}
